starterFiles.style.css:
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: Georgia, serif;
  color: #3b2a1a;
  background: #fff8ee;
}
header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 32px;
  background: #f4c95d;
}
.brand { font-weight: bold; font-size: 20px; }
nav a {
  margin-left: 20px;
  color: #3b2a1a;
  text-decoration: none;
}
.hero {
  padding: 72px 32px;
  text-align: center;
  background: linear-gradient(180deg, #f4c95d 0%, #fff8ee 100%);
}
.hero h1 { font-size: 44px; margin: 0 0 12px; }
.button {
  display: inline-block;
  margin-top: 16px;
  padding: 12px 24px;
  border-radius: 999px;
  background: #3b2a1a;
  color: #fff8ee;
  text-decoration: none;
}
.cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  padding: 32px;
}
.cards article {
  padding: 24px;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 4px 16px rgba(59, 42, 26, 0.08);
}
.cards h2 { margin-top: 0; }
.story { padding: 32px; max-width: 640px; margin: 0 auto; }
footer {
  padding: 24px 32px;
  text-align: center;
  background: #3b2a1a;
  color: #fff8ee;
}
footer p { margin: 4px 0; }

